import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"Launcher exploded-cutaway art — generation recipe (FROZEN)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/launcher-cutaway-style.md","filePath":"guides/launcher-cutaway-style.md"}'),o={name:"guides/launcher-cutaway-style.md"};function r(i,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="launcher-exploded-cutaway-art-—-generation-recipe-frozen" tabindex="-1">Launcher exploded-cutaway art — generation recipe (FROZEN) <a class="header-anchor" href="#launcher-exploded-cutaway-art-—-generation-recipe-frozen" aria-label="Permalink to &quot;Launcher exploded-cutaway art — generation recipe (FROZEN)&quot;">​</a></h1><p>The house recipe for the <strong>exploded-stage cutaway</strong> of a launch vehicle — a richer companion to the single pencil anatomy sketch. Locked with Marko 2026-08-02 after the Saturn V anchor (v3). Match it exactly so the batch reads as one hand and sits happily next to the existing <code>/images/anatomy/*</code> cutaways.</p><p>The look = the <strong>watercolor cutaway</strong> style of the shipped anatomy set (apollo-csm, cassini): watercolor + ink-wash on aged graph paper, warm metallic, margin physics equations, vintage agency markings.</p><hr><h2 id="_0-golden-rules-this-is-where-drift-dies" tabindex="-1">0. Golden rules (this is where drift dies) <a class="header-anchor" href="#_0-golden-rules-this-is-where-drift-dies" aria-label="Permalink to &quot;0. Golden rules (this is where drift dies)&quot;">​</a></h2><ol><li><strong>Model:</strong> always <code>nano_banana_pro</code>. <strong>Aspect:</strong> <code>3:2</code>. <strong>Resolution:</strong> <code>2k</code>.</li><li><strong>Always pass the per-launcher structural SVG sketch as the reference image</strong> (<code>medias:[{value, role:&quot;image&quot;}]</code>). It carries the composition, the stage count, the exact engine counts, and the labels. Text alone will not hold them.</li><li><strong>PROPORTION IS THE THING WE GOT WRONG TWICE — do not repeat it.</strong><ul><li>Each exploded stage is a <strong>TALL, SLENDER cylinder</strong> at its real aspect (S-IC ≈ 4:1, upper stages ≈ 2.5:1). <strong>Never short-and-fat / squat.</strong></li><li>Segments follow the <strong>same proportion as the assembled reference stack at left</strong> — they are the same rocket pulled apart, not re-drawn boxes.</li><li>The prompt MUST keep the clause: <em>&quot;preserving the tall-and-narrow proportions of every stage (do NOT make them short or fat).&quot;</em></li></ul></li><li><strong>Composition (all three, every time):</strong><ul><li><strong>Left:</strong> a small <strong>assembled reference rocket in true proportion</strong> + a tiny <strong>human silhouette</strong> (1.8 m) beside it + a total-height dimension line. This is the size anchor.</li><li><strong>Right:</strong> the pieces <strong>exploded apart in two columns</strong> so each is large + un-squished (big stages in one column, upper pieces/payload in the other).</li><li>Every stage <strong>cut open</strong> to show its LOX + fuel tanks; engines drawn at the base in the <strong>exact count</strong>; fairing/payload + boosters where the vehicle has them.</li></ul></li><li><strong>Vintage, free-to-use agency markings.</strong> Lean into the retro <strong>NASA &quot;worm&quot; and &quot;meatball&quot;</strong> (and each agency&#39;s period logo) — public-domain era markings, flags, stencilled serials. More of that = more awesome (Marko).</li><li><strong>QC every render</strong> against the Saturn V anchor + the anatomy set before committing. Wrong engine count or squat stages → regenerate.</li></ol><h2 id="_1-the-palette-background" tabindex="-1">1. The palette / background <a class="header-anchor" href="#_1-the-palette-background" aria-label="Permalink to &quot;1. The palette / background&quot;">​</a></h2><p>Aged cream <strong>graph paper</strong> with foxing/ink-splatter; warm muted <strong>metallic</strong> (brass, steel, copper); handwritten annotations + thin ruled leader lines; <strong>faint physics equations in the margins</strong>; vintage scientific-sketchbook / editorial-infographic aesthetic. (Same family as the watercolor anatomy recipe in <code>anatomy-art-runbook.md</code> §2 — this is the exploded, multi-stage extension.)</p><h2 id="_2-the-locked-prompt-template-swap-the-bracketed-parts" tabindex="-1">2. The locked prompt template (swap the [bracketed] parts) <a class="header-anchor" href="#_2-the-locked-prompt-template-swap-the-bracketed-parts" aria-label="Permalink to &quot;2. The locked prompt template (swap the [bracketed] parts)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Exploded technical cutaway illustration of the [VEHICLE] rocket, watercolor and</span></span>
<span class="line"><span>ink-wash on faint aged graph paper, exposed internal structure. Follow the</span></span>
<span class="line"><span>reference layout EXACTLY, preserving the tall-and-narrow proportions of every</span></span>
<span class="line"><span>stage (do NOT make them short or fat): at far left a small assembled</span></span>
<span class="line"><span>scale-reference rocket in correct proportion with a tiny human figure beside it</span></span>
<span class="line"><span>and a &#39;[HEIGHT] m&#39; dimension line; the stages exploded apart in two columns,</span></span>
<span class="line"><span>each stage a TALL SLENDER cylinder cut open to reveal its tanks with the engines</span></span>
<span class="line"><span>drawn at the base. Exposed internals: propellant tanks, turbopumps, engine</span></span>
<span class="line"><span>bells[, strap-on boosters]. Handwritten engineering annotations, thin ruled</span></span>
<span class="line"><span>leader lines, dimension lines, faint physics equations in the margins,</span></span>
<span class="line"><span>ink-splatter wash clouds, warm muted metallic palette (brass, steel, copper on</span></span>
<span class="line"><span>cream paper), vintage scientific sketchbook / editorial infographic aesthetic.</span></span>
<span class="line"><span>Vintage [AGENCY] markings (retro logo, flag, stencilled serials). KEEP the</span></span>
<span class="line"><span>engine counts exact ([PER-STAGE COUNTS]), the cut-open [PROPELLANT] tanks, and</span></span>
<span class="line"><span>every label legible and in place: [LABELS]. A warm hand-painted sketchbook</span></span>
<span class="line"><span>cutaway — not a flat vector chart, not photorealistic.</span></span></code></pre></div><h2 id="_3-pipeline" tabindex="-1">3. Pipeline <a class="header-anchor" href="#_3-pipeline" aria-label="Permalink to &quot;3. Pipeline&quot;">​</a></h2><ol><li><code>node scripts/essays/build-cutaway-sketches.mjs</code> — data-driven from <code>src/lib/orbital/launcher-engines.ts</code> (stages, engine counts, arrangement, boosters) + <code>engine-registry.ts</code> (propellants). Emits one structural SVG + PNG per launcher to <code>docs/wip/essay-diagram-sources/launcher-cutaways/</code>.</li><li>Upload each PNG (<code>media_upload</code> → PUT → <code>media_confirm</code>), generate with the template above (up to 8 concurrent, poll <code>job_status sync:true</code>), 2 credits each.</li><li>Download raw PNG → <code>original-assets/launcher-cutaways/&lt;id&gt;.png</code> (committed backup) → resize webp to <code>static/images/anatomy-exploded/&lt;id&gt;.webp</code> (<code>sharp().resize(1600).webp({quality:86})</code>).</li><li>Wire into the fleet DETAIL tab <strong>alongside</strong> the pencil anatomy (a second view, not a replacement). Generated art → no provenance row (Orrery-original).</li></ol><h2 id="_4-where-things-live" tabindex="-1">4. Where things live <a class="header-anchor" href="#_4-where-things-live" aria-label="Permalink to &quot;4. Where things live&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thing</th><th>Path</th></tr></thead><tbody><tr><td>Structural sketches (input)</td><td><code>docs/wip/essay-diagram-sources/launcher-cutaways/*.svg</code></td></tr><tr><td>Generated originals (backup)</td><td><code>original-assets/launcher-cutaways/*.png</code></td></tr><tr><td>Served display images</td><td><code>static/images/anatomy-exploded/*.webp</code></td></tr><tr><td>Sketch generator</td><td><code>scripts/essays/build-cutaway-sketches.mjs</code></td></tr><tr><td>Reference anchor</td><td>Saturn V v3 (<code>saturn-v-exploded</code>) — the north star</td></tr></tbody></table><h2 id="_5-manual-exceptions-—-do-not-regenerate-these-from-the-generator" tabindex="-1">5. Manual exceptions — do NOT regenerate these from the generator <a class="header-anchor" href="#_5-manual-exceptions-—-do-not-regenerate-these-from-the-generator" aria-label="Permalink to &quot;5. Manual exceptions — do NOT regenerate these from the generator&quot;">​</a></h2><p>The <code>build-cutaway-sketches.mjs</code> generator encodes ONE model: an <strong>in-line tandem stack</strong> (cylindrical stages atop each other, tank split + engine bells per stage, one representative booster, a fairing+payload cone on top). That is correct for ~70% of the fleet but structurally WRONG for vehicles that deviate. These 7 were <strong>hand-authored from corrected prose</strong> (2026-08-02), anchored to the Saturn V for style, and passed NO generator sketch. Re-running the generator for them would reintroduce the wrong geometry — edit the prose instead.</p><table tabindex="0"><thead><tr><th>id</th><th>Why the generator is wrong</th><th>Corrected to</th></tr></thead><tbody><tr><td><code>space-shuttle-stack</code></td><td>Side-mount, not a tandem stack</td><td>Orbiter (3× RS-25) + External Tank (no engines) + 2 SRBs, exploded</td></tr><tr><td><code>soyuz</code></td><td>Strap-ons cluster around the core, not stacked</td><td>Korolev cross — 4 conical boosters around Blok-A core</td></tr><tr><td><code>vostok-k</code></td><td>Same, + spherical capsule not a fairing</td><td>Korolev cross + spherical Vostok capsule</td></tr><tr><td><code>voskhod-11a57</code></td><td>Same cluster</td><td>Korolev cross around the core</td></tr><tr><td><code>titan-ii-glv</code></td><td>Flew a bare capsule, no fairing</td><td>Bare Gemini capsule on top, no clamshell</td></tr><tr><td><code>atlas-lv-3b</code></td><td>Bare capsule + escape tower, no fairing</td><td>Mercury capsule + escape tower, stage-and-a-half</td></tr><tr><td><code>mercury-redstone</code></td><td>Bare capsule + escape tower, no fairing</td><td>Mercury capsule + escape tower, single stage</td></tr></tbody></table><p>The corrected prose for each lives in the git history of this session; regenerate from that, not from a generator sketch.</p>`,18)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
